CREATE FUNCTION public.protect_creator_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN IF TG_OP='INSERT' AND NEW.verification_status<>'self_reported' THEN RAISE EXCEPTION 'Evidence status is controlled by reviewers'; END IF; IF TG_OP='UPDATE' AND NEW.verification_status IS DISTINCT FROM OLD.verification_status THEN RAISE EXCEPTION 'Evidence status is controlled by reviewers'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_creator_evidence BEFORE INSERT OR UPDATE ON public.creator_profiles FOR EACH ROW EXECUTE FUNCTION public.protect_creator_evidence();